cat > app/javascript/helpers/date_helpers.js <<'EOF'
const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000
const RELATIVE_DAYS_LIMIT = 6

const timeFormatter = new Intl.DateTimeFormat("en-US", {
  hour: "numeric",
  minute: "2-digit"
})

const dateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric"
})

const fullDateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric"
})

const weekdayDateFormatter = new Intl.DateTimeFormat("en-US", {
  weekday: "long",
  month: "long",
  day: "numeric"
})

const dateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  year: "numeric",
  month: "numeric",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit"
})

const relativeDayFormatter = new Intl.RelativeTimeFormat("en-US", {
  numeric: "auto"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return dayNumber(toDate) - dayNumber(fromDate)
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function formatLocalTime(date, format = "relative", now = new Date()) {
  if (isNaN(date)) return ""

  switch (format) {
    case "time":
      return timeFormatter.format(date)
    case "date":
      return formatDate(date, now)
    case "full_date":
    case "full-date":
      return fullDateFormatter.format(date)
    case "weekday_date":
    case "weekday-date":
      return formatWeekdayDate(date, now)
    case "datetime":
      return dateTimeFormatter.format(date)
    default:
      return formatRelative(date, now)
  }
}

function formatRelative(date, now) {
  const difference = signedDifferenceInDays(now, date)

  if (difference === 0) {
    return date <= now ? timeFormatter.format(date) : "today"
  } else if (difference === -1) {
    return "yesterday"
  } else if (difference === 1) {
    return "tomorrow"
  } else if (Math.abs(difference) <= RELATIVE_DAYS_LIMIT) {
    return relativeDayFormatter.format(difference, "day")
  } else {
    return formatDate(date, now)
  }
}

function formatDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return dateFormatter.format(date)
  } else {
    return fullDateFormatter.format(date)
  }
}

function formatWeekdayDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return weekdayDateFormatter.format(date)
  } else {
    return `${weekdayDateFormatter.format(date)}, ${date.getFullYear()}`
  }
}

function dayNumber(date) {
  return Math.round(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / DAY_IN_MILLISECONDS)
}
EOF

