# The browser sends its timezone in a cookie so we can keep the user's saved
# timezone up to date. Rendering always uses the application's stable timezone:
# timestamps are formatted by the browser, so responses can be cached and shared
# between people in different timezones.
module CurrentTimezone
  extend ActiveSupport::Concern

  included do
    helper_method :timezone_from_cookie
  end

  private
    def timezone_from_cookie
      @timezone_from_cookie ||= begin
        timezone = cookies[:timezone]
        ActiveSupport::TimeZone[timezone] if timezone.present?
      end
    end
end
