module TimeHelper
  # Renders a <time> element containing only the raw timestamp. The browser is
  # responsible for formatting it in the viewer's timezone.
  #
  # format can be one of: :relative, :time, :date, :full_date, :weekday_date,
  # :datetime. See app/javascript/helpers/date_helpers.js for the exact output.
  def local_time(time, format = nil, date_only: nil, **attributes)
    return if time.blank?

    format = attributes.delete(:format) || format || :relative
    date_only = date_only?(time) if date_only.nil?

    data = (attributes.delete(:data) || {}).merge(
      controller: "local-time",
      local_time_format_value: format
    )
    data[:local_time_date_only_value] = true if date_only

    tag.time(nil, **attributes, datetime: timestamp_for(time, date_only:), data:)
  end

  def local_date(date, format = :date, **attributes)
    local_time(date, format, date_only: true, **attributes)
  end

  private
    def date_only?(time)
      time.is_a?(Date) && !time.is_a?(Time)
    end

    def timestamp_for(time, date_only:)
      if date_only
        time.to_date.iso8601
      else
        time.iso8601
      end
    end
end
--- local_time controller
import { Controller } from "@hotwired/stimulus"
import { formatLocalTime } from "helpers/date_helpers"

export default class extends Controller {
  static values = {
    format: { type: String, default: "relative" },
    dateOnly: Boolean
  }

  connect() {
    this.render()
  }

  render() {
    const timestamp = this.element.getAttribute("datetime")
    const date = this.dateOnlyValue ? parseLocalDate(timestamp) : new Date(timestamp)

    this.element.textContent = formatLocalTime(date, this.formatValue)
  }
}

function parseLocalDate(value) {
  const [ year, month, day ] = value.split("-").map(Number)
  return new Date(year, month - 1, day)
}
--- date helpers
const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000
const RELATIVE_DAYS_LIMIT = 6

const timeFormatter = new Intl.DateTimeFormat("en-US", {
  hour: "numeric",
  minute: "2-digit"
})

const dateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric"
})

const fullDateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric"
})

const weekdayDateFormatter = new Intl.DateTimeFormat("en-US", {
  weekday: "long",
  month: "long",
  day: "numeric"
})

const dateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  year: "numeric",
  month: "numeric",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit"
})

const relativeDayFormatter = new Intl.RelativeTimeFormat("en-US", {
  numeric: "auto"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return dayNumber(toDate) - dayNumber(fromDate)
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function formatLocalTime(date, format = "relative", now = new Date()) {
  if (isNaN(date)) return ""

  switch (format) {
    case "time":
      return timeFormatter.format(date)
    case "date":
      return formatDate(date, now)
    case "full_date":
    case "full-date":
      return fullDateFormatter.format(date)
    case "weekday_date":
    case "weekday-date":
      return formatWeekdayDate(date, now)
    case "datetime":
      return dateTimeFormatter.format(date)
    default:
      return formatRelative(date, now)
  }
}

function formatRelative(date, now) {
  const difference = signedDifferenceInDays(now, date)

  if (difference === 0) {
    return date <= now ? timeFormatter.format(date) : "today"
  } else if (difference === -1) {
    return "yesterday"
  } else if (difference === 1) {
    return "tomorrow"
  } else if (Math.abs(difference) <= RELATIVE_DAYS_LIMIT) {
    return relativeDayFormatter.format(difference, "day")
  } else {
    return formatDate(date, now)
  }
}

function formatDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return dateFormatter.format(date)
  } else {
    return fullDateFormatter.format(date)
  }
}

function formatWeekdayDate(date, now) {
  if (date.getFullYear() === now.getFullYear()) {
    return weekdayDateFormatter.format(date)
  } else {
    return `${weekdayDateFormatter.format(date)}, ${date.getFullYear()}`
  }
}

function dayNumber(date) {
  return Math.round(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / DAY_IN_MILLISECONDS)
}
