--- share controller
import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatLocalTime } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "share"

  shareUrl() {
    const description = this.#formattedDescription
    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: description
    })
  }

  get #formattedDescription() {
    const description = this.bridgeElement.bridgeAttribute("share-description")
    if (!description) return description

    return description
      .replace("%{added}", this.#formattedDate("share-added-at"))
      .replace("%{updated}", this.#formattedDate("share-updated-at"))
  }

  #formattedDate(attribute) {
    const timestamp = this.bridgeElement.bridgeAttribute(attribute)
    return timestamp ? formatLocalTime(new Date(timestamp), "date") : ""
  }
}
--- stamp controller
import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatLocalTime } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "stamp"
  static values = { scopeSelector: { type: String, default: "body" }, date: String }

  connect() {
    super.connect()

    if (this.element.closest(this.scopeSelectorValue)) {
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: formatLocalTime(new Date(this.dateValue), "full_date")
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true
    })
  }
}

